import { createRequire } from "node:module";
import { flavor } from "#external";
import { exact } from "#exact";
import { condition } from "#condition";
import { pattern } from "#pattern/value";

const require = createRequire(import.meta.url);
const required = require("#mode");

export const summary = [exact, pattern, condition, flavor, required.mode].join(":");

export async function importedMode() {
  return (await import("#mode")).mode;
}
